def draft(lang,category,cited,needs_human,has_claimed_ref=False):
    t=TEMPLATES.get(lang,TEMPLATES['ru'])
    lines=[t['hello'],t['topics'].get(category,t['received'])]
    if has_claimed_ref:lines.append(t['rule'])
    lines.append(t['review'] if needs_human else t['missing'])
    return ' '.join(lines)
